inline const Entry* FindTimer(std::int32_t structId) {
    int lo = 0, hi = (int)(sizeof(kTimer) / sizeof(kTimer[0])) - 1;
    while (lo <= hi) { int m = (lo + hi) / 2; if (kTimer[m].structId == structId) return &kTimer[m]; if (kTimer[m].structId < structId) lo = m + 1; else hi = m - 1; }
    return nullptr;
}
